func (this *Test_org_eclipse_swt_graphics_Image) Test_bug566545_efficientGrayscaleImage() {
	var grayscale []*swt.RGB = make([]*swt.RGB, 256)
	for i := int32(0); i < int32(len(grayscale)); i++ {
		grayscale[i] = swt.NewRGB(i, i, i)
	}
	var width int32 = 128
	var height int32 = 128
	var imageDataIndexed *swt.ImageData = swt.NewImageData(width, height, 8, swt.NewPaletteData(grayscale))
	var imageDataDirect *swt.ImageData = swt.NewImageData(width, height, 8, swt.NewPaletteDataRedMaskGreenMaskBlueMask(0xFF, 0xFF, 0xFF))
	var fillImage func(*swt.ImageData) = func(imageData *swt.ImageData) {
		for y := int32(0); y < imageData.Height; y++ {
			for x := int32(0); x < imageData.Width; x++ {
				imageData.SetPixel(x, y, (x+y)%256)
			}
		}
	}
	fillImage(imageDataIndexed)
	fillImage(imageDataDirect)
	var imageIndexed *swt.Image = swt.NewImageDeviceData(upcastswtDisplayToswtDevice(this.display), imageDataIndexed)
	var imageDirect *swt.Image = swt.NewImageDeviceData(upcastswtDisplayToswtDevice(this.display), imageDataDirect)
	var gcDrawer1 swt.ImageGcDrawer = &ImageGcDrawerFunc{fn: func(gc *swt.GC, iWidth int32, iHeight int32) {
		gc.DrawImage(imageIndexed, 0, 0)
	}}
	var outImageIndexed *swt.Image = swt.NewImageDeviceImageGcDrawerWidthHeight(upcastswtDisplayToswtDevice(this.display), gcDrawer1, width, height)
	var gcDrawer2 swt.ImageGcDrawer = &ImageGcDrawerFunc{fn: func(gc *swt.GC, iWidth int32, iHeight int32) {
		gc.DrawImage(imageDirect, 0, 0)
	}}
	var outImageDirect *swt.Image = swt.NewImageDeviceImageGcDrawerWidthHeight(upcastswtDisplayToswtDevice(this.display), gcDrawer2, width, height)
	ImageTestUtilAssertImagesEqual(imageDataIndexed, imageDataDirect)
	ImageTestUtilAssertImagesEqual(imageIndexed.GetImageData(), imageDirect.GetImageData())
	ImageTestUtilAssertImagesEqual(outImageIndexed.GetImageData(), outImageDirect.GetImageData())
	imageIndexed.Dispose()
	imageDirect.Dispose()
	outImageIndexed.Dispose()
	outImageDirect.Dispose()
}

func (this *Test_org_eclipse_swt_graphics_Image) Test_drawImageAtSize_doesNotReReadFileOfNonSizableFormat() {
	var file *jrt.Path = Test_org_eclipse_swt_graphics_ImageTempFolder.Resolve("volatile-collapseall.png")
	jrt.FilesCopy(jrt.PathOf(Test_org_eclipse_swt_graphics_ImageGetPath("collapseall.png"), []string{}), file, []any{})
	var previousDeviceZoom int32 = swt.DPIUtilGetDeviceZoom()
	swt.DPIUtilSetDeviceZoom(100)
	{
		defer func() {
			swt.DPIUtilSetDeviceZoom(previousDeviceZoom)
			jrt.FilesDeleteIfExists(file)
		}()
		var image *swt.Image = swt.NewImageDeviceFilename(upcastswtDisplayToswtDevice(this.display), file.ToString())
		var target *swt.Image = swt.NewImageDeviceWidthHeight(upcastswtDisplayToswtDevice(this.display), 64, 64)
		var gc *swt.GC = swt.NewGCDrawable(upcastswtImageToswtDrawable(target))
		func() {
			defer func() {
				gc.Dispose()
				target.Dispose()
				image.Dispose()
			}()
			var bounds *swt.Rectangle = image.GetBounds()
			gc.DrawImageImageDestXDestYDestWidthDestHeight(image, 0, 0, bounds.Width*2, bounds.Height*2)
			jrt.FilesDelete(file)
			gc.DrawImageImageDestXDestYDestWidthDestHeight(image, 0, 0, bounds.Width*2, bounds.Height*2)
			gc.DrawImageImageDestXDestYDestWidthDestHeight(image, 0, 0, bounds.Width*3, bounds.Height*3)
		}()
	}
}

func (this *Test_org_eclipse_swt_graphics_Image) Test_drawImageAtSize_reevaluatesSizabilityWhenFileNameChanges() {
	var sizableFile *jrt.Path = Test_org_eclipse_swt_graphics_ImageTempFolder.Resolve("switchable-collapseall.svg")
	jrt.FilesCopy(jrt.PathOf(Test_org_eclipse_swt_graphics_ImageGetPath("collapseall.svg"), []string{}), sizableFile, []any{})
	var currentFile *jrt.AtomicReference = jrt.NewAtomicReference(Test_org_eclipse_swt_graphics_ImageGetPath("collapseall.png"))
	var switchingProvider swt.ImageFileNameProvider = &ImageFileNameProviderFunc{fn: func(zoom int32) string {
		var cond37 string
		if zoom == 100 {
			cond37 = jrt.Cast[string](currentFile.Get())
		} else {
			cond37 = ""
		}
		return cond37
	}}
	var previousDeviceZoom int32 = swt.DPIUtilGetDeviceZoom()
	swt.DPIUtilSetDeviceZoom(100)
	{
		defer func() {
			swt.DPIUtilSetDeviceZoom(previousDeviceZoom)
			jrt.FilesDeleteIfExists(sizableFile)
		}()
		var image *swt.Image = swt.NewImageDeviceImageFileNameProvider(upcastswtDisplayToswtDevice(this.display), switchingProvider)
		var target *swt.Image = swt.NewImageDeviceWidthHeight(upcastswtDisplayToswtDevice(this.display), 64, 64)
		var gc *swt.GC = swt.NewGCDrawable(upcastswtImageToswtDrawable(target))
		func() {
			defer func() {
				gc.Dispose()
				target.Dispose()
				image.Dispose()
			}()
			gc.DrawImageImageDestXDestYDestWidthDestHeight(image, 0, 0, 20, 20)
			currentFile.Set(sizableFile.ToString())
			gc.DrawImageImageDestXDestYDestWidthDestHeight(image, 0, 0, 20, 20)
			jrt.FilesDelete(sizableFile)
			junit.AssertThrows[*swt.SWTException](func() {
				gc.DrawImageImageDestXDestYDestWidthDestHeight(image, 0, 0, 24, 24)
			}, "the file of a sizable image must be read again for a new size")
		}()
	}
}

